void tryChange(int x) {
    x = 100;      /* 복사본만 바뀐다 */
}

int main(void) {
    int a = 5;
    tryChange(a);
    printf("%d\n", a);   /* 5 — 바뀌지 않았다 */
    return 0;
}

void change(int *x) {
    *x = 100;     /* 가리키는 곳에 직접 쓴다 */
}

int main(void) {
    int a = 5;
    change(&a);           /* 주소를 넘긴다 */
    printf("%d\n", a);    /* 100 */
    return 0;
}

void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int x = 1, y = 2;
swap(&x, &y);
printf("%d %d\n", x, y);   /* 2 1 */

void f(int x, int *y) {
    x = 10;
    *y = 20;
}
