int factorial(int n) {
    if (n <= 1) return 1;        /* 종료 조건 */
    return n * factorial(n - 1); /* 더 작은 문제로 */
}

printf("%d\n", factorial(5));   /* 120 */

int f(int n) {
    if (n == 0) return 0;
    return n + f(n - 1);
}
int main(void) {
    printf("%d\n", f(4));
    return 0;
}

